1: #!/usr/bin/env node
2: /**
3:  * git-ab.mjs — 打印「本地相对 upstream 的 ahead / behind」，杜绝读反
4:  * `git rev-list --left-right --count` 的左右两列（审计 P3-14：agent 曾把
5:  * `0  1` 读成「落后 1」，实际是「领先 1」，多做一次空转 rebase）。
6:  *
7:  * 用法：
8:  *   node git-ab.mjs                      # 当前目录，不 fetch
9:  *   node git-ab.mjs <worktree-path>      # 指定 worktree / 仓库路径
10:  *   node git-ab.mjs <worktree-path> --fetch <branch>   # 先 git fetch origin <branch>
11:  *
12:  * 输出（一行，便于模型解析）：
13:  *   ahead=<X> behind=<Y> upstream=<origin/branch> raw=<behind>\t<ahead>
14:  *
15:  * 语义（rev-list --left-right --count UPSTREAM...HEAD）：
16:  *   左列 = 只在 UPSTREAM 里的提交 = behind（本地缺的）
17:  *   右列 = 只在 HEAD 里的提交     = ahead（本地多的）
18:  * 本脚本在 Node 里用 execFileSync 传独立参数，不经过 shell，因此 `@{u}` 不会被
19:  * PowerShell 当成哈希字面量；也不受 `head/tail` 之类 POSIX 命令缺失影响。
20:  */
21: 
22: import { execFileSync } from "node:child_process";
23: 
24: const argv = process.argv.slice(2);
25: 
26: /** 取位置参数里的路径（第一个不以 `--` 开头的参数）。 */
27: function repoPath() {
28:   for (const a of argv) {
29:     if (!a.startsWith("--")) return a;
30:   }
31:   return process.cwd();
32: }
33: 
34: /** 取 `--fetch <branch>` 的 branch（可选）。 */
35: function fetchBranch() {
36:   const i = argv.indexOf("--fetch");
37:   return i >= 0 && i + 1 < argv.length ? argv[i + 1] : undefined;
38: }
39: 
40: function git(args, cwd) {
41:   return execFileSync("git", args, { cwd, encoding: "utf8", stdio: ["ignore", "pipe", "pipe"] }).trim();
42: }
43: 
44: const cwd = repoPath();
45: const branch = fetchBranch();
46: 
47: try {
48:   if (branch) {
49:     git(["fetch", "origin", branch], cwd);
50:   }
51: } catch (error) {
52:   console.error(`git-ab: git fetch origin ${branch} 失败：${error.stderr?.toString?.() ?? error.message}`);
53:   process.exit(2);
54: }
55: 
56: let upstream;
57: try {
58:   upstream = git(["rev-parse", "--abbrev-ref", "--symbolic-full-name", "@{u}"], cwd);
59: } catch {
60:   // 没有设置 upstream：退回 origin/<当前分支>。
61:   try {
62:     const cur = git(["rev-parse", "--abbrev-ref", "HEAD"], cwd);
63:     upstream = `origin/${cur}`;
64:   } catch (error) {
65:     console.error(`git-ab: 无法确定 upstream：${error.message}`);
66:     process.exit(2);
67:   }
68: }
69: 
70: let raw;
71: try {
72:   raw = git(["rev-list", "--left-right", "--count", `${upstream}...HEAD`], cwd);
73: } catch (error) {
74:   console.error(`git-ab: rev-list 失败（upstream=${upstream}）：${error.message}`);
75:   process.exit(2);
76: }
77: 
78: // raw 形如 "0\t1" 或 "3\t2"。
79: const [behindStr, aheadStr] = raw.split(/\s+/);
80: const behind = Number(behindStr);
81: const ahead = Number(aheadStr);
82: if (!Number.isFinite(behind) || !Number.isFinite(ahead)) {
83:   console.error(`git-ab: 无法解析 rev-list 输出：${JSON.stringify(raw)}`);
84:   process.exit(2);
85: }
86: 
87: console.log(`ahead=${ahead} behind=${behind} upstream=${upstream} raw=${behind}\t${ahead}`);

